import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as a}from"./app-X6fsa0X9.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/MySQL/01_%E5%9F%BA%E7%A1%80%E7%AF%87/02_%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%E4%B8%8E%E8%A1%A8%E8%AE%BE%E8%AE%A1.html","title":"数据类型与表设计","lang":"zh-CN","frontmatter":{"title":"数据类型与表设计","icon":"fa6-brands:mysql","order":2,"category":["数据库","MySQL"],"tag":["MySQL","数据类型","表设计","字符集"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":9.66,"words":2897},"filePathRelative":"后端开发/数据库/MySQL/01_基础篇/02_数据类型与表设计.md"}`),s={name:`02_数据类型与表设计.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="数据类型与表设计" tabindex="-1"><a class="header-anchor" href="#数据类型与表设计"><span>数据类型与表设计</span></a></h1><p>选错数据类型，轻则浪费存储，重则导致精度丢失、索引失效甚至数据截断。本文梳理 MySQL 常用数据类型的选型要点，并给出表设计的实战建议。</p><h2 id="_1-数值类型" tabindex="-1"><a class="header-anchor" href="#_1-数值类型"><span>1. 数值类型</span></a></h2><h3 id="_1-1-整数类型" tabindex="-1"><a class="header-anchor" href="#_1-1-整数类型"><span>1.1 整数类型</span></a></h3><table><thead><tr><th>类型</th><th>字节</th><th>有符号范围</th><th>无符号范围</th><th>典型场景</th></tr></thead><tbody><tr><td>TINYINT</td><td>1</td><td>-128 ~ 127</td><td>0 ~ 255</td><td>状态枚举、布尔</td></tr><tr><td>SMALLINT</td><td>2</td><td>-32768 ~ 32767</td><td>0 ~ 65535</td><td>年龄、排序值</td></tr><tr><td>MEDIUMINT</td><td>3</td><td>-8388608 ~ 8388607</td><td>0 ~ 16777215</td><td>中等范围 ID</td></tr><tr><td>INT</td><td>4</td><td>-2^31 ~ 2^31-1</td><td>0 ~ 2^32-1</td><td>主键、外键、数量</td></tr><tr><td>BIGINT</td><td>8</td><td>-2^63 ~ 2^63-1</td><td>0 ~ 2^64-1</td><td>大 ID、金额（分）</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 创建用户表，展示整型选型</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> users</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id         </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#ABB2BF;">    age        </span><span style="color:#C678DD;">TINYINT</span><span style="color:#ABB2BF;"> UNSIGNED COMMENT </span><span style="color:#98C379;">&#39;0~255 足够&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    status</span><span style="color:#C678DD;">     TINYINT</span><span style="color:#ABB2BF;">         COMMENT </span><span style="color:#98C379;">&#39;-128~127, 负值表示异常状态&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    point</span><span style="color:#C678DD;">      INT</span><span style="color:#ABB2BF;"> UNSIGNED    </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;积分&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    PRIMARY KEY</span><span style="color:#ABB2BF;"> (id)</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#ABB2BF;"> CHARSET </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- INT(11) 的 display width 不影响存储范围！</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL 8.0.17+ 已废弃 display width，仅保留用于元数据兼容</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> demo</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    a </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">11</span><span style="color:#ABB2BF;">),   </span><span style="color:#7F848E;font-style:italic;">-- 存储范围仍是 -2^31 ~ 2^31-1</span></span>
<span class="line"><span style="color:#ABB2BF;">    b </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">),    </span><span style="color:#7F848E;font-style:italic;">-- 和 INT(11) 占用相同空间，范围相同</span></span>
<span class="line"><span style="color:#ABB2BF;">    c </span><span style="color:#C678DD;">INT</span><span style="color:#7F848E;font-style:italic;">        -- 推荐写法，省略 display width</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">INT(11) 不是长度限制</p><p><code>INT(11)</code> 中的 11 是<strong>显示宽度</strong>（display width），仅在搭配 <code>ZEROFILL</code> 时有视觉作用，不影响存储范围和取值范围。<code>INT(1)</code> 和 <code>INT(11)</code> 存储的值完全相同。MySQL 8.0.17 起已废弃 display width，新代码请直接写 <code>INT</code>。</p></div><h3 id="_1-2-定点数与浮点数" tabindex="-1"><a class="header-anchor" href="#_1-2-定点数与浮点数"><span>1.2 定点数与浮点数</span></a></h3><table><thead><tr><th>类型</th><th>字节</th><th>精度</th><th>适用场景</th></tr></thead><tbody><tr><td>FLOAT</td><td>4</td><td>约 7 位有效数字</td><td>科学计算，可接受精度损失</td></tr><tr><td>DOUBLE</td><td>8</td><td>约 15 位有效数字</td><td>统计分析</td></tr><tr><td>DECIMAL(M,D)</td><td>变长</td><td>精确</td><td><strong>金额、财务</strong></td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 金额存储：DECIMAL 是唯一正确选择</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> orders</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id           </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_amount </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;总金额，最大 9999999999.99&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    discount     </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)   </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;折扣金额&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    pay_method   </span><span style="color:#C678DD;">TINYINT</span><span style="color:#C678DD;">         NOT NULL</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;支付方式&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 浮点数精度陷阱</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 结果: 0.3（凑巧正确）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 结果: 0.020000...（精度丢失）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- DECIMAL 精确计算</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)) * </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">2</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果: 0.02</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">金额存储的两种方案</p><ol><li><strong>DECIMAL(12,2)</strong>：直观，SQL 层直接计算，存储占用较大</li><li><strong>BIGINT 存分</strong>：1.23 元存为 123，存储紧凑、计算快、无精度问题，但需要应用层做换算</li></ol><p>生产推荐 BIGINT 存分，兼顾性能和精度。</p></div><h2 id="_2-字符串类型" tabindex="-1"><a class="header-anchor" href="#_2-字符串类型"><span>2. 字符串类型</span></a></h2><h3 id="_2-1-类型对比" tabindex="-1"><a class="header-anchor" href="#_2-1-类型对比"><span>2.1 类型对比</span></a></h3><table><thead><tr><th>类型</th><th>最大长度</th><th>存储特点</th><th>典型场景</th></tr></thead><tbody><tr><td>CHAR(N)</td><td>255 字符</td><td>定长，不足补空格</td><td>MD5、手机号、固定编码</td></tr><tr><td>VARCHAR(N)</td><td>65535 字节</td><td>变长，1-2 字节长度前缀</td><td>用户名、地址、描述</td></tr><tr><td>TINYTEXT</td><td>255 字节</td><td>变长，1 字节长度前缀</td><td>短文本</td></tr><tr><td>TEXT</td><td>65535 字节</td><td>变长，2 字节长度前缀</td><td>文章内容</td></tr><tr><td>MEDIUMTEXT</td><td>16 MB</td><td>变长，3 字节长度前缀</td><td>长文章、富文本</td></tr><tr><td>LONGTEXT</td><td>4 GB</td><td>变长，4 字节长度前缀</td><td>超大文本（极少用）</td></tr><tr><td>BLOB 系列</td><td>同 TEXT</td><td>二进制存储</td><td>图片、序列化数据</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> articles</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id         </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#ABB2BF;">    title      </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">200</span><span style="color:#ABB2BF;">)  </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;标题&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    author     </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">64</span><span style="color:#ABB2BF;">)   </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    content    MEDIUMTEXT    COMMENT </span><span style="color:#98C379;">&#39;正文，支持长文&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    summary    </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">500</span><span style="color:#ABB2BF;">)  COMMENT </span><span style="color:#98C379;">&#39;摘要&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    cover_url  </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">512</span><span style="color:#ABB2BF;">)  COMMENT </span><span style="color:#98C379;">&#39;封面图 URL&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    tags       </span><span style="color:#C678DD;">JSON</span><span style="color:#ABB2BF;">          COMMENT </span><span style="color:#98C379;">&#39;标签数组，8.0+ 特性&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    created_at </span><span style="color:#C678DD;">DATETIME</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)   </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#ABB2BF;"> CHARSET </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-varchar-长度选择的坑" tabindex="-1"><a class="header-anchor" href="#_2-2-varchar-长度选择的坑"><span>2.2 VARCHAR 长度选择的坑</span></a></h3>`,16),i(d,{code:``}),o[1]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 行大小超限演示</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> too_big</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    a </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">22000</span><span style="color:#ABB2BF;">),  </span><span style="color:#7F848E;font-style:italic;">-- utf8mb4 下约 88000 字节</span></span>
<span class="line"><span style="color:#ABB2BF;">    b </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">22000</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ERROR 1118 (42000): Row size too large.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- The maximum row size is 65535 bytes, including BLOBs.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 正确做法：合理规划列长度</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> reasonable</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    a </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">255</span><span style="color:#ABB2BF;">),   </span><span style="color:#7F848E;font-style:italic;">-- 名称类</span></span>
<span class="line"><span style="color:#ABB2BF;">    b </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">512</span><span style="color:#ABB2BF;">),   </span><span style="color:#7F848E;font-style:italic;">-- 短描述</span></span>
<span class="line"><span style="color:#ABB2BF;">    c </span><span style="color:#C678DD;">TEXT</span><span style="color:#7F848E;font-style:italic;">             -- 长文本单独存</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#ABB2BF;"> CHARSET </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">VARCHAR(N) 对索引的影响</p><p>InnoDB 索引键长度限制为 3072 字节（utf8mb4 下约 768 个字符）。VARCHAR 过长会导致无法创建索引或索引被截断。建议索引列的 VARCHAR 长度不超过 255。</p></div><h2 id="_3-日期与时间类型" tabindex="-1"><a class="header-anchor" href="#_3-日期与时间类型"><span>3. 日期与时间类型</span></a></h2><h3 id="_3-1-类型对比" tabindex="-1"><a class="header-anchor" href="#_3-1-类型对比"><span>3.1 类型对比</span></a></h3><table><thead><tr><th>类型</th><th>字节</th><th>格式</th><th>范围</th><th>时区处理</th></tr></thead><tbody><tr><td>DATE</td><td>3</td><td>YYYY-MM-DD</td><td>1000-01-01 ~ 9999-12-31</td><td>无</td></tr><tr><td>TIME</td><td>3</td><td>HH:MM:SS</td><td>-838:59:59 ~ 838:59:59</td><td>无</td></tr><tr><td>DATETIME</td><td>8</td><td>YYYY-MM-DD HH:MM:SS</td><td>1000-01-01 00:00:00 ~ 9999-12-31 23:59:59</td><td><strong>不转换</strong>，存什么读什么</td></tr><tr><td>TIMESTAMP</td><td>4</td><td>YYYY-MM-DD HH:MM:SS</td><td>1970-01-01 00:00:01 ~ 2038-01-19 03:14:07</td><td><strong>自动转换</strong>，存 UTC 读本地</td></tr><tr><td>YEAR</td><td>1</td><td>YYYY</td><td>1901 ~ 2155</td><td>无</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> time_demo</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id           </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#ABB2BF;">    created_at   </span><span style="color:#C678DD;">DATETIME</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)    </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    updated_at   </span><span style="color:#C678DD;">DATETIME</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)     </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">ON UPDATE</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    published_at </span><span style="color:#C678DD;">TIMESTAMP</span><span style="color:#C678DD;">       NULL</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;发布时间，自动时区转换&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    birthday     </span><span style="color:#C678DD;">DATE</span><span style="color:#C678DD;">            NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    work_years   </span><span style="color:#C678DD;">YEAR</span><span style="color:#ABB2BF;">            COMMENT </span><span style="color:#98C379;">&#39;入职年份&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- DATETIME vs TIMESTAMP 时区行为</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> time_zone </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;+08:00&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 北京时间</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> time_demo (published_at) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;2025-01-15 10:30:00&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> time_zone </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;+00:00&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- UTC</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> published_at </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> time_demo;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果: 2025-01-15 02:30:00  （自动从 +08 转为 +00）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- DATETIME 不受时区影响</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 存入 2025-01-15 10:30:00，读取始终是 2025-01-15 10:30:00</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">DATETIME vs TIMESTAMP 选型建议</p><ul><li><strong>业务时间</strong>（订单创建、文章发布）：用 <code>DATETIME(3)</code>，不随时区变化，含义明确</li><li><strong>系统时间</strong>（记录变更、日志时间戳）：用 <code>TIMESTAMP</code>，自动时区转换，4 字节更紧凑</li><li><strong>TIMESTAMP 2038 问题</strong>：范围只到 2038-01-19，超出范围必须用 DATETIME</li><li><strong>小数秒精度</strong>：<code>DATETIME(3)</code> 表示毫秒，<code>DATETIME(6)</code> 表示微秒，推荐至少保留 3 位</li></ul></div><h2 id="_4-json-类型-mysql-8-0" tabindex="-1"><a class="header-anchor" href="#_4-json-类型-mysql-8-0"><span>4. JSON 类型（MySQL 8.0+）</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> products</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id          </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;">        VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">200</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    attrs       </span><span style="color:#C678DD;">JSON</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;动态属性&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    created_at  </span><span style="color:#C678DD;">DATETIME</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)  </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_name ((</span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(attrs-</span><span style="color:#56B6C2;">&gt;&gt;</span><span style="color:#98C379;">&#39;$.brand&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> CHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">64</span><span style="color:#ABB2BF;">))))  </span><span style="color:#7F848E;font-style:italic;">-- 函数索引</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#ABB2BF;"> CHARSET </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 插入 JSON 数据</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> products (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, attrs) </span><span style="color:#C678DD;">VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;iPhone 16&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;{&quot;brand&quot;: &quot;Apple&quot;, &quot;color&quot;: &quot;太空灰&quot;, &quot;storage&quot;: 256, &quot;specs&quot;: {&quot;cpu&quot;: &quot;A18&quot;, &quot;ram&quot;: 8}}&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;Galaxy S24&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;{&quot;brand&quot;: &quot;Samsung&quot;, &quot;color&quot;: &quot;暮光紫&quot;, &quot;storage&quot;: 128, &quot;specs&quot;: {&quot;cpu&quot;: &quot;Snapdragon 8 Gen 3&quot;, &quot;ram&quot;: 12}}&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- JSON 查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">, attrs-</span><span style="color:#56B6C2;">&gt;&gt;</span><span style="color:#98C379;">&#39;$.brand&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> brand, attrs-</span><span style="color:#56B6C2;">&gt;</span><span style="color:#98C379;">&#39;$.storage&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> storage</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> attrs-</span><span style="color:#56B6C2;">&gt;&gt;</span><span style="color:#98C379;">&#39;$.brand&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Apple&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- JSON 修改</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> products</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> attrs </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> JSON_SET(attrs, </span><span style="color:#98C379;">&#39;$.storage&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">512</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- JSON 表函数（8.0.14+），展开嵌套数据</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> jt.*</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products,</span></span>
<span class="line"><span style="color:#ABB2BF;">     JSON_TABLE(attrs, </span><span style="color:#98C379;">&#39;$.specs&#39;</span><span style="color:#ABB2BF;"> COLUMNS(</span></span>
<span class="line"><span style="color:#ABB2BF;">         cpu </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">64</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PATH</span><span style="color:#98C379;"> &#39;$.cpu&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">         ram </span><span style="color:#C678DD;">INT</span><span style="color:#C678DD;"> PATH</span><span style="color:#98C379;"> &#39;$.ram&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">     )) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> jt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">JSON 的适用场景</p><p>JSON 类型适合<strong>稀疏属性</strong>（不同商品有不同属性），但不适合频繁查询过滤的字段。对 JSON 字段的查询无法直接使用索引，必须借助<strong>生成列 + 索引</strong>或 MySQL 8.0 的<strong>函数索引</strong>。</p></div><h2 id="_5-字符集与排序规则" tabindex="-1"><a class="header-anchor" href="#_5-字符集与排序规则"><span>5. 字符集与排序规则</span></a></h2><h3 id="_5-1-utf8-vs-utf8mb4" tabindex="-1"><a class="header-anchor" href="#_5-1-utf8-vs-utf8mb4"><span>5.1 utf8 vs utf8mb4</span></a></h3><table><thead><tr><th>字符集</th><th>每字符最大字节</th><th>支持 Emoji</th><th>状态</th></tr></thead><tbody><tr><td>utf8 (utf8mb3)</td><td>3</td><td>❌</td><td>MySQL 8.0 已标记废弃</td></tr><tr><td>utf8mb4</td><td>4</td><td>✅</td><td><strong>推荐</strong></td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- utf8 无法存储 Emoji 的演示</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> NAMES utf8;</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> users (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;张三😀&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ERROR 1366 (HY000): Incorrect string value</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- utf8mb4 正确存储</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> NAMES utf8mb4;</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> users (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;张三😀&#39;</span><span style="color:#ABB2BF;">);  </span><span style="color:#7F848E;font-style:italic;">-- ✅ 成功</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-排序规则-collation" tabindex="-1"><a class="header-anchor" href="#_5-2-排序规则-collation"><span>5.2 排序规则（Collation）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 常用排序规则</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- utf8mb4_general_ci：不区分大小写， accent-insensitive（é=e），速度快</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- utf8mb4_unicode_ci：不区分大小写，Unicode 正确排序，略慢</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- utf8mb4_0900_ai_ci：MySQL 8.0 默认，基于 Unicode 9.0，accent-insensitive</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- utf8mb4_bin：区分大小写，二进制比较</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 大小写敏感比较</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#98C379;"> &#39;Hello&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;hello&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- utf8mb4_0900_ai_ci: 1（不区分）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> BINARY</span><span style="color:#98C379;"> &#39;Hello&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;hello&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 0（区分）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 指定排序规则</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> COLLATE</span><span style="color:#ABB2BF;"> utf8mb4_zh_0900_as_cs;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- zh: 中文拼音排序, as: accent-sensitive, cs: case-sensitive</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">生产环境统一设置</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- my.cnf 配置</span></span>
<span class="line"><span style="color:#E06C75;">[mysqld]</span></span>
<span class="line"><span style="color:#ABB2BF;">character_set_server </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4</span></span>
<span class="line"><span style="color:#ABB2BF;">collation_server </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4_0900_ai_ci</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">[client]</span></span>
<span class="line"><span style="color:#C678DD;">default</span><span style="color:#ABB2BF;">-</span><span style="color:#C678DD;">character</span><span style="color:#ABB2BF;">-</span><span style="color:#C678DD;">set</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> utf8mb4</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>数据库、表、列、连接四个层面的字符集必须一致，否则可能出现乱码或索引失效。</p></div><h2 id="_6-行大小限制" tabindex="-1"><a class="header-anchor" href="#_6-行大小限制"><span>6. 行大小限制</span></a></h2><p>MySQL 行大小硬限制为 <strong>65535 字节</strong>（所有列总和），InnoDB 页内限制为页大小的一半（默认 8KB）。</p>`,19),i(d,{code:``}),o[2]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 计算行大小</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- VARCHAR(255) utf8mb4 = 255 * 4 + 2 = 1022 字节</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 64 个这样的列 = 64 * 1022 = 65408 字节 &lt; 65535 ✅</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 65 个 = 65 * 1022 = 66430 字节 &gt; 65535 ❌</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 溢出页机制</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- VARCHAR / TEXT 超过约 768 字节时，前 768 字节存于页内</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 剩余数据存于溢出页，页内仅保留 20 字节指针</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 这是 TEXT 类型不影响 65535 行限制的原因</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_7-表设计实战" tabindex="-1"><a class="header-anchor" href="#_7-表设计实战"><span>7. 表设计实战</span></a></h2><h3 id="_7-1-三范式-vs-反范式" tabindex="-1"><a class="header-anchor" href="#_7-1-三范式-vs-反范式"><span>7.1 三范式 vs 反范式</span></a></h3>`,3),i(d,{code:``}),o[3]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 3NF 设计：订单与订单项分离</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> orders</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id          </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#ABB2BF;">    user_id     </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_amount </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    status</span><span style="color:#C678DD;">      TINYINT</span><span style="color:#C678DD;">        NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    created_at  </span><span style="color:#C678DD;">DATETIME</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)    </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_user (user_id),</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_status_created (</span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, created_at)</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#ABB2BF;"> CHARSET </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> order_items</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id          </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#ABB2BF;">    order_id    </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    product_id  </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    product_name </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">200</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;冗余：防止商品改名影响历史订单&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    quantity    </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;"> UNSIGNED  </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    unit_price  </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;冗余：下单时快照&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_order (order_id),</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_product (product_id)</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#ABB2BF;"> CHARSET </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 反范式设计：查询频繁的统计字段冗余到主表</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">ADD</span><span style="color:#ABB2BF;"> COLUMN item_count </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;冗余：避免 COUNT(order_items)&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">ADD</span><span style="color:#ABB2BF;"> COLUMN order_count </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;冗余：避免关联统计&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-从-dbeaver-看表结构设计" tabindex="-1"><a class="header-anchor" href="#_7-2-从-dbeaver-看表结构设计"><span>7.2 从 DBeaver 看表结构设计</span></a></h3><p>使用 <a href="https://github.com/dbeaver/dbeaver" target="_blank" rel="noopener noreferrer">DBeaver</a> 可以可视化查看表结构和 ER 关系：</p><ol><li>连接数据库后，右键数据库 → <strong>ER Diagram</strong> → 生成实体关系图</li><li>双击表 → <strong>Data</strong> 标签页查看实际数据，<strong>Properties</strong> 查看列定义</li><li>右键表 → <strong>Generate SQL</strong> → 查看建表 DDL</li></ol><div class="hint-container tip"><p class="hint-container-title">表设计检查清单</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> 主键使用 <code>BIGINT UNSIGNED AUTO_INCREMENT</code> 或雪花 ID</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> 所有字段 <code>NOT NULL</code> + 合理 DEFAULT，避免 NULL 带来的索引和统计问题</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 金额用 <code>DECIMAL</code> 或 <code>BIGINT 存分</code></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> 时间用 <code>DATETIME(3)</code> 或 <code>TIMESTAMP</code></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> 字符集统一 <code>utf8mb4</code></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> VARCHAR 长度按实际业务上限设置，不要一味给大</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> TEXT/BLOB 不与高频查询列同表，考虑分表</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> 适当冗余减少 JOIN，特别是高并发读场景</label></li></ul></div><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container important"><p class="hint-container-title">高频考点</p><ol><li><strong>INT(11) 的含义</strong>：display width，不影响存储和范围，8.0.17+ 已废弃。很多面试者答错。</li><li><strong>DATETIME vs TIMESTAMP</strong>：TIMESTAMP 4 字节、自动时区转换、2038 限制；DATETIME 8 字节、不受时区影响。核心区别是时区处理方式。</li><li><strong>utf8 vs utf8mb4</strong>：MySQL 的 utf8 是 utf8mb3（最多 3 字节），不支持 Emoji；utf8mb4 才是真正的 UTF-8。MySQL 8.0 已废弃 utf8mb3。</li><li><strong>VARCHAR 最大长度</strong>：65535 字节限制（非字符数），受字符集和行内其他列影响。</li><li><strong>金额存储</strong>：DECIMAL vs BIGINT 存分，后者更推荐。FLOAT/DOUBLE 绝对不能用于金额。</li><li><strong>3NF 与反范式</strong>：面试常问&quot;什么时候违反第三范式&quot;，答案：高并发读场景下适当冗余减少 JOIN。</li><li><strong>JSON 类型</strong>：8.0 新增，适合稀疏属性，查询需借助函数索引。</li></ol></div><div class="hint-container tip"><p class="hint-container-title">参考资源</p><ul><li><a href="https://xiaolincoding.com/mysql/" target="_blank" rel="noopener noreferrer">小林coding - MySQL 数据类型</a>：面试常考的数据类型对比</li><li><a href="https://dev.mysql.com/doc/refman/8.0/en/data-types.html" target="_blank" rel="noopener noreferrer">MySQL 8.0 官方文档 - Data Types</a>：完整类型参考</li><li><a href="https://github.com/dbeaver/dbeaver" target="_blank" rel="noopener noreferrer">DBeaver</a>：可视化查看表结构和 ER 图</li></ul></div>`,8)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};